<template><SuperAdminLayout><main class="audit"><header><div><h1>Audit Logs</h1><p>View all important actions performed in the system</p></div><div><small>Last Updated:<b>{{dateTime(updated)}}</b></small><button @click="load">↻</button></div></header><section class="filters"><form @submit.prevent="apply"><label>Date From<input v-model="f.from" type="date"></label><label>Date To<input v-model="f.to" type="date"></label><label>Customer No.<input v-model="f.customer" placeholder="All"></label><label>Company Name<input v-model="f.company" placeholder="All"></label><label>Admin / User Name<input v-model="f.user" placeholder="All"></label><label>Module<select v-model="f.module"><option value="">All</option><option>Login</option><option>Customers Management</option><option>Sales & Payments</option><option>Security Settings</option></select></label><label>Action Type<select v-model="f.action"><option value="">All</option><option>Login</option><option>Logout</option><option>Updated</option><option>Disabled</option></select></label><label>IP Address<input v-model="f.ip" placeholder="Enter IP Address"></label><label>Status<select v-model="f.status"><option value="">All</option><option>Successful</option><option>Failed</option><option>Blocked</option></select></label><div><button class="primary">⌕ &nbsp; Search</button><button type="button" @click="reset">↻ &nbsp; Reset</button><button type="button" @click="exportCsv">⇩ &nbsp; Export⌄</button></div></form></section><section class="list"><header><h2>Audit Log List</h2><strong>Total Records: {{filtered.length}}</strong></header><div class="table"><table><thead><tr><th>No.</th><th>Date</th><th>Time</th><th>Customer No.</th><th>Company Name</th><th>Admin / User Name</th><th>Module</th><th>Action</th><th>Previous Value</th><th>New Value</th><th>IP Address</th><th>Device / Browser</th><th>Location</th><th>Status</th><th>Reason / Notes</th><th>View Details</th></tr></thead><tbody><tr v-for="(r,i) in paged" :key="i"><td>{{(page-1)*perPage+i+1}}</td><td>{{shortDate(r.date)}}</td><td>{{r.time||'—'}}</td><td>{{r.customer_number||'—'}}</td><td>{{r.customer}}</td><td>{{r.user}}</td><td>{{r.module}}</td><td>{{r.action}}</td><td>{{r.previous_value||'—'}}</td><td>{{r.new_value||'—'}}</td><td>{{r.ip_address||'—'}}</td><td>{{r.device||'—'}}</td><td>{{r.location||'—'}}</td><td><span :class="['status',String(r.status).toLowerCase()]">{{r.status||'—'}}</span></td><td>{{r.notes||'—'}}</td><td><button class="view" @click="detail=r">View</button></td></tr><tr v-if="!paged.length"><td colspan="16">No audit log records match these filters.</td></tr></tbody></table></div><footer><span>Showing {{paged.length?(page-1)*perPage+1:0}} to {{Math.min(page*perPage,filtered.length)}} of {{filtered.length}} entries</span><div><button :disabled="page===1" @click="page=1">First</button><button :disabled="page===1" @click="page--">Previous</button><b>{{page}}</b><button :disabled="page>=pages" @click="page++">Next</button><button :disabled="page>=pages" @click="page=pages">Last</button></div><label>Rows per page:<select v-model.number="perPage" @change="page=1"><option :value="10">10</option><option :value="25">25</option><option :value="50">50</option></select></label></footer></section><section class="important"><span>ⓘ</span><div><b>Important</b><p>Audit logs are system records and cannot be edited or deleted.</p></div></section><div v-if="detail" class="modal" @click.self="detail=null"><article><button @click="detail=null">×</button><h2>Audit Log Details</h2><p v-for="(value,key) in detail" :key="key"><b>{{title(key)}}:</b> {{value||'—'}}</p></article></div></main></SuperAdminLayout></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const rows=ref([]),page=ref(1),perPage=ref(10),updated=ref(new Date().toISOString()),detail=ref(null),f=reactive({from:'',to:'',customer:'',company:'',user:'',module:'',action:'',ip:'',status:''}),title=x=>String(x).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase()),shortDate=x=>x?new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit',year:'numeric'}).format(new Date(x)):'—',dateTime=x=>x?new Intl.DateTimeFormat('en-US',{month:'short',day:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(x)):'—';const filtered=computed(()=>rows.value.filter(r=>{const at=new Date(r.date),text=Object.values(r).join(' ').toLowerCase();return(!f.from||at>=new Date(f.from))&&(!f.to||at<=new Date(`${f.to}T23:59:59`))&&(!f.customer||String(r.customer_number||'').toLowerCase().includes(f.customer.toLowerCase()))&&(!f.company||String(r.customer||'').toLowerCase().includes(f.company.toLowerCase()))&&(!f.user||String(r.user||'').toLowerCase().includes(f.user.toLowerCase()))&&(!f.module||r.module===f.module)&&(!f.action||text.includes(f.action.toLowerCase()))&&(!f.ip||String(r.ip_address||'').includes(f.ip))&&(!f.status||String(r.status||'').toLowerCase()===f.status.toLowerCase())})),pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/perPage.value))),paged=computed(()=>filtered.value.slice((page.value-1)*perPage.value,page.value*perPage.value));async function load(){const r=await client.get('/super-admin/audit-logs');rows.value=r.data.data?.data||[];updated.value=new Date().toISOString()}function apply(){page.value=1}function reset(){Object.assign(f,{from:'',to:'',customer:'',company:'',user:'',module:'',action:'',ip:'',status:''});page.value=1}function exportCsv(){const csv=['Date,Time,Company,User,Module,Action,IP Address,Status',...filtered.value.map(r=>[r.date,r.time,r.customer,r.user,r.module,r.action,r.ip_address,r.status].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(','))].join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='audit-logs.csv';a.click();URL.revokeObjectURL(url)}onMounted(load)</script>
<style scoped>.audit{color:#071d58;min-width:0}.audit>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.audit h1{margin:0;font-size:2rem}.audit>header p{margin:5px 0 0;font-size:.86rem}.audit>header>div:last-child{display:flex;align-items:center;gap:15px}.audit>header small{text-align:right;font-size:.7rem}.audit>header small b{display:block;margin-top:4px;font-size:.76rem}.audit>header button{width:55px;height:40px;border:1px solid #ccd9ec;border-radius:5px;background:#fff;color:#09256b;font-size:1.2rem}.filters,.list{box-sizing:border-box;width:100%;border:1px solid #d9e3ef;border-radius:7px;background:#fff}.filters{padding:16px 18px;margin-bottom:16px}.filters form{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:15px 24px}.filters label{display:grid;gap:6px;min-width:0;font-size:.68rem;font-weight:700}.filters input,.filters select,.filters button,.list footer select{box-sizing:border-box;min-width:0;height:35px;border:1px solid #cfdbeb;border-radius:5px;background:#fff;padding:0 10px;color:#172552;font:500 .75rem inherit}.filters div{grid-column:4/-1;display:flex;gap:22px;align-items:end}.filters div button{flex:1;font-weight:700;cursor:pointer}.filters .primary{background:#06236f;border-color:#06236f;color:#fff}.list>header{display:flex;justify-content:space-between;padding:11px 16px;border-bottom:1px solid #dce5ef}.list h2{margin:0;font-size:.85rem}.list header strong{font-size:.72rem}.table{overflow:auto}.table table{width:100%;min-width:1400px;border-collapse:collapse;font-size:.64rem}.table th,.table td{padding:9px 7px;border:1px solid #e2e8f0;text-align:center}.table th{background:linear-gradient(100deg,#03205f,#0751c7)!important;color:#fff!important;font-size:.6rem}.status{display:inline-block;padding:3px 6px;border-radius:3px;background:#e8f7ed;color:#168242;font-size:.62rem}.status.failed{background:#ffe3e3;color:#d80e0e}.status.blocked{background:#f0e6ff;color:#7822ce}.view{border:0;background:transparent;color:#0757d7;font:600 .65rem inherit;cursor:pointer}.list footer{display:flex!important;justify-content:space-between;align-items:center;padding:12px;background:#fff!important;background-image:none!important;color:#0a205c!important;font-size:.69rem}.list footer div{display:flex;gap:7px}.list footer button,.list footer b{display:grid;place-items:center;min-width:42px;height:29px;border:1px solid #d3deec;border-radius:4px;background:#fff;color:#0d2366;font:600 .68rem inherit}.list footer b{background:#082169;color:#fff}.list footer label{display:flex;align-items:center;gap:8px}.important{display:flex;gap:13px;margin-top:12px;padding:15px 18px;border:1px solid #b9d6ff;border-radius:6px;background:#eef6ff}.important>span{font-size:1.35rem;color:#073d9f}.important b{font-size:.78rem}.important p{margin:9px 0 0;font-size:.7rem}.modal{position:fixed;z-index:50;inset:0;display:grid;place-items:center;background:#071d5880}.modal article{position:relative;max-width:460px;max-height:80vh;overflow:auto;padding:22px;border-radius:8px;background:#fff}.modal article>button{position:absolute;right:9px;top:5px;border:0;background:none;font-size:1.45rem}.modal h2{margin-top:0}.modal p{font-size:.78rem}@media(max-width:700px){.audit>header{display:block}.audit>header>div:last-child{margin-top:12px;justify-content:space-between}.filters form{grid-template-columns:1fr}.filters div{grid-column:auto}.list footer{display:block!important}.list footer div{margin:10px 0}.audit h1{font-size:1.55rem}}</style>
